INSERT OR IGNORE INTO home_spotlight (id, title) VALUES (1, 'Congratulations to our Newly-certified Full Stack Developers!');
INSERT OR IGNORE INTO home_spotlight_people (id, payload) VALUES (1, '{"id":1,"displayName":"Ardione, David","fullName":"Ardione David","certification":"Certified Full Stack Developer","headshot":"assets/images/headshot-ardione-david.jpg.png","bio":"Ardione David is a certified full stack developer who possesses a comprehensive skill set to build and maintain full-stack web applications, ensuring seamless integration between the front-end and back-end components while effectively managing data storage and retrieval, and application security. He''s proficient in front-end using ReactJS with Vite, while NestJS for backend, with the use of Postgres and SQLite for database.","image":"assets/images/congrats3.png"}');
INSERT OR IGNORE INTO home_spotlight_people (id, payload) VALUES (2, '{"id":2,"displayName":"Bayona, Mark Anthony","fullName":"Mark Anthony Bayona","certification":"Certified Full Stack Developer","headshot":"assets/images/headshot-bayona-mark-anthony.jpg.png","bio":"Mark Anthony Bayona is a certified full stack developer who possesses a comprehensive skill set to build and maintain full-stack web applications, ensuring seamless integration between the front-end and back-end components while effectively managing data storage and retrieval, and application security. He''s proficient in front-end using ReactJS, while NestJS/Prisma for backend, with the use of Postgres for database.","image":"assets/images/congrats1.png"}');
INSERT OR IGNORE INTO home_spotlight_people (id, payload) VALUES (3, '{"id":3,"displayName":"Fernandez, Henry","fullName":"Henry Fernandez","certification":"Certified Full Stack Developer","headshot":"assets/images/headshot-fernandez-henry.jpg.png","bio":"Henry Fernandez is a certified full stack developer who possesses a comprehensive skill set to build and maintain full-stack web applications, ensuring seamless integration between the front-end and back-end components while effectively managing data storage and retrieval, and application security. He''s proficient in front-end using ReactJS, while NestJS for backend, with the use of Postgres for database.","image":"assets/images/congrats4.png"}');
INSERT OR IGNORE INTO home_spotlight_people (id, payload) VALUES (4, '{"id":4,"displayName":"Ignacio, Alison","fullName":"Alison Ignacio","certification":"Certified Full Stack Developer","headshot":"assets/images/headshot-ignacio-alison.jpg.png","bio":"Alison Ignacio is a certified full stack developer who possesses a comprehensive skill set to build and maintain full-stack web applications, ensuring seamless integration between the front-end and back-end components while effectively managing data storage and retrieval, and application security. He''s proficient in front-end using ReactJS, while NestJS/Prisma for backend, with the use of MySQL for database.","image":"assets/images/congrats2.png"}');
