INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 2, '{"title":"Accenture Support","description":"Centralized, self-service framework for employees to access assistance across technology, human resources, and internal operations.","linkText":"Accenture Support","url":"https://support.accenture.com","external":true}');
INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 3, '{"title":"Buhay Accenture","description":"Official internal site for Accenture in the Philippines, serving as the primary hub for company news, culture, and employee resources.","linkText":"Buhay Accenture","url":"https://in.accenture.com/philippines/","external":true}');
INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 4, '{"title":"IS Advocate","description":"Increase security awareness and promote secure behavior adoption by completing assigned interactive learning activities as well as track progress, and improve Secure Behavior Score (SBS) in the Information Security Advocate Dashboard.","linkText":"IS Advocate Dashboard","url":"https://isadvocate.accenture.com/","external":true}');
