INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 6, '{"title":"Philippine Employee Self-service Hub (PESH)","description":"One-stop hub exclusive for Philippines employees to get employee-related information and requests and offers extensive list of features like comprehensive pay slips, donations and leave balances.","linkText":"PESH","url":"https://pesh.accenture.com/home","external":true}');
INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 7, '{"title":"Workday: ABCD Reflection","description":"ABCD self-reflections is your opportunity to reflect on your Areas of Impact, Behaviors, Collaboration, and Development. You can use this as preparation for a talent discussion and/or career conversation.","linkText":"Workday: ABCD Reflection","url":"https://wd103.myworkday.com/accenture/d/task/12709$1289.htmld","external":true}');
INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 8, '{"title":"Workday: CV","description":"Create or generate a default one-pager CV with the help of AI, or access your a full-version of your CV with detailed sections.","linkText":"Workday: CV","url":"https://wd103.myworkday.com/accenture/d/task/2998$2739.htmld#TABTASKID=21200%241","external":true}');
INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 9, '{"title":"Workday: Skills and Specialization","description":"Map employee skills, experience, and specializations to support career growth, learning recommendations, and talent management.","linkText":"Workday: Skills and Specialization","url":"https://wd103.myworkday.com/accenture/d/task/2998$2739.htmld#TABTASKID=21200%24300","external":true}');
INSERT OR IGNORE INTO song_link_cards (section_id, card_id, payload) VALUES (2, 10, '{"title":"Workday: Trainings","description":"Enhance growth through personalized, skills-driven recommendations and embedded learning in daily workflows. Search, enroll, and track a wide selection of courses, while providing managers with tools to assign training and monitor team progress.","linkText":"Workday: Trainings","url":"https://wd103.myworkday.com/accenture/learning","external":true}');
